DType d_td_core_Option = {"Option", 2, v_option, 1, 1, NULL};
DType d_td_core_Result = {"Result", 2, v_result, 1, 1, NULL};
DType d_td_core_Error = {"Error", 1, v_error, 0, 0, NULL};
